class PermitType(Enum):
    SCOUT = "scout"
    EXPLORER = "explorer"
    UNKNOWN = "unknown"


class OxygenState(Enum):
    FULL = "full"
    DEPLETED = "depleted"
    RECHARGING = "recharging"
    EMPTY = "empty"


class TransactionStatus(Enum):
    PENDING = "pending"
    COMMITTED = "committed"
    FAILED = "failed"
    ROLLED_BACK = "rolled_back"


class ValidationError(Exception):
    """Raised when validation fails."""
    pass


class InsufficientFundsError(ValidationError):
    """Raised when balance is insufficient for a purchase."""
    pass


class NegativePriceError(ValidationError):
    """Raised when price is negative."""
    pass


class DepthExceededError(ValidationError):
    """Raised when requested depth exceeds permit limit."""
    pass


class UnknownLicenseError(ValidationError):
    """Raised when license type is unknown or unrecognized."""
    pass


class OxygenTransitionError(ValidationError):
    """Raised when an invalid oxygen state transition is attempted."""
    pass


class DuplicateRequestError(Exception):
    """Raised for idempotency checks - not an error, but a signal to return cached result."""
    def __init__(self, request_id: str, cached_result: Any):
        self.request_id = request_id
        self.cached_result = cached_result
        super().__init__(f"Duplicate request {request_id}")


@dataclass(frozen=True)
class Permit:
    """Represents a diving permit with depth limits."""
    permit_type: PermitType
    max_depth: int

    def __post_init__(self):
        if not isinstance(self.max_depth, int):
            raise ValidationError("max_depth must be an integer")
        if self.max_depth < 0:
            raise ValidationError("max_depth cannot be negative")


@dataclass(frozen=True)
class Item:
    """Represents a purchasable item."""
    item_id: str
    price: int
    name: str = ""

    def __post_init__(self):
        if not isinstance(self.price, int):
            raise ValidationError("price must be an integer")
        if self.price < 0:
            raise ValidationError("price cannot be negative")
        if not self.item_id or not isinstance(self.item_id, str):
            raise ValidationError("item_id must be a non-empty string")


@dataclass
class InventoryState:
    """Represents the current inventory state."""
    balance: int = 0
    items: Dict[str, int] = field(default_factory=dict)
    oxygen_level: int = 100
    oxygen_state: OxygenState = OxygenState.FULL
    permit: Optional[Permit] = None
    current_depth: int = 0

    def __post_init__(self):
        if not isinstance(self.balance, int):
            raise ValidationError("balance must be an integer")
        if self.balance < 0:
            raise ValidationError("balance cannot be negative")
        if not isinstance(self.oxygen_level, int):
            raise ValidationError("oxygen_level must be an integer")
        if self.oxygen_level < 0 or self.oxygen_level > 100:
            raise ValidationError("oxygen_level must be between 0 and 100")
        if not isinstance(self.current_depth, int):
            raise ValidationError("current_depth must be an integer")
        if self.current_depth < 0:
            raise ValidationError("current_depth cannot be negative")


@dataclass(frozen=True)
class Transaction:
    """Represents a transaction record."""
    request_id: str
    item_id: str
    price: int
    status: TransactionStatus
    timestamp: float
    balance_before: int
    balance_after: Optional[int] = None
    error_message: Optional[str] = None

    def __post_init__(self):
        if not isinstance(self.price, int):
            raise ValidationError("price must be an integer")
        if self.price < 0:
            raise ValidationError("price cannot be negative")
        if not isinstance(self.balance_before, int):
            raise ValidationError("balance_before must be an integer")


@dataclass(frozen=True)
class OxygenEvent:
    """Represents an oxygen state transition event."""
    event_id: str
    from_state: OxygenState
    to_state: OxygenState
    level_before: int
    level_after: int
    timestamp: float

    def __post_init__(self):
        if not isinstance(self.level_before, int) or not isinstance(self.level_after, int):
            raise ValidationError("oxygen levels must be integers")
        if self.level_before < 0 or self.level_before > 100:
            raise ValidationError("level_before out of range")
        if self.level_after < 0 or self.level_after > 100:
            raise ValidationError("level_after out of range")


