        if not isinstance(self.from_depth, int) or not isinstance(self.to_depth, int):
            raise ValidationError("depths must be integers")
        if self.from_depth < 0 or self.to_depth < 0:
            raise ValidationError("depths cannot be negative")


@dataclass(frozen=True)
class PurchaseEvent:
    """Represents a purchase event."""
    event_id: str
    item_id: str
    price: int
    balance_before: int
    balance_after: int
    timestamp: float

    def __post_init__(self):
        if not isinstance(self.price, int) or not isinstance(self.balance_before, int) or not isinstance(self.balance_after, int):
            raise ValidationError("all numeric fields must be integers")


@dataclass(frozen=True)
class SaveSnapshot:
