    state: InventoryState
    timestamp: float
    checksum: str

    def __post_init__(self):
        if not self.snapshot_id or not isinstance(self.snapshot_id, str):
            raise ValidationError("snapshot_id must be a non-empty string")
        if not self.checksum or not isinstance(self.checksum, str):
            raise ValidationError("checksum must be a non-empty string")


class PermitValidator:
    """Validates permit types and depth limits."""

    # From FACT-E: scout permit allows depth <= 24; explorer permits depth <= 42
    PERMIT_LIMITS = {
        PermitType.SCOUT: 24,
        PermitType.EXPLORER: 42,
    }

    @staticmethod
    def get_permit(permit_type_str: str) -> Permit:
        """Get permit object from string type. Unknown licenses fail closed."""
        if not isinstance(permit_type_str, str):
            raise UnknownLicenseError(f"Permit type must be a string, got {type(permit_type_str)}")

        try:
            permit_type = PermitType(permit_type_str.lower())
        except ValueError:
            # Unknown license - fail closed
            raise UnknownLicenseError(f"Unknown permit type: {permit_type_str}")

        if permit_type == PermitType.UNKNOWN:
            raise UnknownLicenseError("UNKNOWN permit type is not valid for diving")

        max_depth = PermitValidator.PERMIT_LIMITS.get(permit_type)
        if max_depth is None:
            raise UnknownLicenseError(f"No depth limit defined for permit type: {permit_type}")

        return Permit(permit_type=permit_type, max_depth=max_depth)

    @staticmethod
    def validate_depth(depth: int, permit: Permit) -> bool:
        """Validate that depth is within permit limits. Inclusive boundary."""
        if not isinstance(depth, int):
            raise ValidationError("depth must be an integer")
        if depth < 0:
            raise ValidationError("depth cannot be negative")

        # From FACT-E: A depth exactly at the limit is allowed
        return depth <= permit.max_depth

    @staticmethod
    def can_dive(depth: int, permit_type_str: str) -> bool:
        """Check if a character with given permit can dive to specified depth."""
        try:
            permit = PermitValidator.get_permit(permit_type_str)
            return PermitValidator.validate_depth(depth, permit)
        except UnknownLicenseError:
            # Fail closed for unknown licenses
            return False


